{
  "segment_function": "definition",
  "claims": [
    {
      "claim": "The polis is defined as the organization of people arising from acting and speaking together, with its true space lying between people living together for this purpose rather than its physical location.",
      "claim_type": "author_position",
      "supporting_excerpt": "The polis , properly speaking, is not the city-state in its physical location; it is the organization of the people as it arises out of acting and speaking together, and its true space lies between people living together for this purpose, no matter where they happen to be.",
      "support_kind": "direct",
      "qualifications": [],
      "confidence": 1
    },
    {
      "claim": "Power springs up between people when they act together and vanishes the moment they disperse, remaining distinct from the natural quality of individual strength.",
      "claim_type": "author_position",
      "supporting_excerpt": "While strength is the natural quality of an individual seen in isolation, power springs up between men when they act together and vanishes the moment they disperse.",
      "support_kind": "direct",
      "qualifications": [],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "The polis",
      "definition": "The organization of the people as it arises out of acting and speaking together, whose true space lies between people living together for this purpose regardless of physical location."
    },
    {
      "term": "The space of appearance",
      "definition": "The space where I appear to others as others appear to me, where men make their appearance explicitly, coming into being wherever men are together in the manner of speech and action."
    },
    {
      "term": "Power",
      "definition": "A power potential that springs up between men when they act together, exists only in its actualization, and keeps the public realm in existence."
    },
    {
      "term": "Strength",
      "definition": "The natural quality of an individual seen in isolation."
    }
  ],
  "distinctions": [
    {
      "item_a": "Power",
      "item_b": "Strength",
      "distinction": "Strength is the natural quality of an individual seen in isolation, whereas power springs up between men when they act together and vanishes the moment they disperse."
    },
    {
      "item_a": "Power",
      "item_b": "Violence",
      "distinction": "Power cannot be stored up and kept in reserve for emergencies like the instruments of violence, but exists only in its actualization."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "The spatial and relational nature of the polis and the space of appearance.",
    "The conceptual distinction between power (as potential actualized in word and deed) and individual strength or stored instruments of violence."
  ]
}

